#!/usr/bin/env bash
# deploy_finans_hold.sh — Finans odasini GECICI KAPAT: hardcoded sayili odayi temiz placeholder ile degistir.
# Sadece shells/finans.html. server_container.mjs / bi.js'e DOKUNMAZ (yetki-matrisi oturumuyla cakismaz).
# SUNUCUDA: cd /opt/krb-assessment && bash deploy_finans_hold.sh
set -euo pipefail
cd /opt/krb-assessment
TS=$(date +%Y%m%d_%H%M%S)
echo "== [1] finans.html yedek + placeholder yaz =="
cp shells/finans.html "finans.html.bak_hold_$TS" 2>/dev/null || true
base64 -d > shells/finans.html <<'B64_EOF'

B64_EOF
echo "  placeholder $(wc -c < shells/finans.html) bayt · hardcoded sayi: $(grep -oE '[0-9]+[.,][0-9]+M|%[0-9]+' shells/finans.html | wc -l)"
echo "== [2] build + deploy =="
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== [3] dogrula =="
echo "  marker (1 bekle): $(docker exec krb-assessment grep -c FINANS_ODASI_HOLD_V1 /app/shells/finans.html)"
echo "  hardcoded M/%% sayi (0 bekle): $(docker exec krb-assessment sh -c \"grep -oE '[0-9]+[.,][0-9]+M|%[0-9]+' /app/shells/finans.html | wc -l\")"
echo "  eski hardcoded oda gitti (ROTA 19,9 aramasi 0 bekle): $(docker exec krb-assessment sh -c \"grep -c '19,9M' /app/shells/finans.html || true\")"
echo "== [4] fingerprint =="
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform <<'SQL_EOF'
INSERT INTO bi_insa_gunlugu (adim, ne, neden, detay)
SELECT 'FINANS_ODASI_HOLD_V1','Finans odasi GECICI KAPATILDI: shells/finans.html -> temiz placeholder (sifir hardcoded sayi). Route /api/bi/finans-odasi ayni, sadece icerik placeholder.','Oda prototip hardcoded sayilarla canliya cikmisti (ROTA 19,9M vb ~70 sabit rakam + FIN defaults); Fatih kurali: SIFIR hardcoded. Sahte sayi gostermemek icin oda kapatildi, tam veri-gudumlu yeniden kurulacak.','{"marker":"FINANS_ODASI_HOLD_V1","dosya":"shells/finans.html","durum":"gecici-kapali","sonraki":"tam-canli-yeniden-kurulum","referans":"finans_ref_hardcoded.html"}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM bi_insa_gunlugu WHERE adim='FINANS_ODASI_HOLD_V1');
SQL_EOF
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform -c "SELECT adim FROM bi_insa_gunlugu WHERE adim='FINANS_ODASI_HOLD_V1'"
echo "== BITTI — Finans odasi placeholder (sifir hardcoded). Route/sekme ayni; icerik 'hazirlaniyor'. Cmd+Shift+R. =="
